class StationError(Exception):
    """Something the field station refuses to do."""


def set_zone(name):
    if name not in ("north", "east", "south", "west"):
        raise StationError("unknown zone: " + str(name))
    return name


try:
    set_zone("attic")
except StationError as err:
    print(err)
